CREATE OR REPLACE TRIGGER PBMS.TRIG_PPM_PRODUCT
      AFTER INSERT OR DELETE OR UPDATE ON PBMS.PPM_INVENTORY_ITEM       FOR EACH ROW
DISABLE
BEGIN
      IF INSERTING THEN
        INSERT INTO AHN.LOG_SAMPLE_PRODUCT
        values (:NEW.PPM_CODE, :NEW.PPM_DESC,'I', SYSDATE);
     ELSIF UPDATING THEN
        INSERT INTO AHN.LOG_SAMPLE_PRODUCT
       values (:NEW.PPM_CODE, :NEW.PPM_DESC,'U', SYSDATE);
     ELSE
        INSERT INTO AHN.LOG_SAMPLE_PRODUCT
        values (:OLD.PPM_CODE, :OLD.PPM_DESC,'D', SYSDATE);
     END IF;
    END;
/


