(
  REQ_NO           VARCHAR2(21 BYTE)            NOT NULL,
  PPM_CODE         VARCHAR2(10 BYTE)            NOT NULL,
  PPM_SPECI_GROUP  VARCHAR2(5 BYTE)             NOT NULL,
  REQ_ITEM_NO      VARCHAR2(23 BYTE),
  REQ_QNTY         NUMBER(12),
  STCH_CODE        VARCHAR2(2 BYTE),
  REQUIRED_DT      DATE,
  TMODE            VARCHAR2(1 BYTE),
  QUAT_NO          VARCHAR2(15 BYTE),
  CNCL_FLAG        VARCHAR2(1 BYTE),
  CNCL_REASON      VARCHAR2(125 BYTE),
  RCV_STORE        VARCHAR2(2 BYTE),
  QNTY_PER_PACK    NUMBER(10),
  NOF_PACK         NUMBER(10),
  PLAN_MON         DATE,
  IND_NO           VARCHAR2(15 BYTE),
  CHINA_CODE       VARCHAR2(22 BYTE),
  ORD_FLAG         VARCHAR2(1 BYTE),
  EDIT_BY          VARCHAR2(5 BYTE),
  EDIT_DT          DATE,
  ASSIGN_EMP_CODE  VARCHAR2(5 BYTE)
)
TABLESPACE USERS
PCTUSED    0
PCTFREE    10
INITRANS   1
